/** 図柄の座標（画面座標・任意単位）を、実際の場所の緯度経度に変換（rot だけ回して置く） */
export function ancientSegments(g) {
  const bb = bboxOf(g.strokes);
  const k = g.size / Math.max(bb.w, bb.h);
  const [ax, ay] = g.anchor || [bb.minX + bb.w / 2, bb.minY + bb.h / 2];
  const th = ((g.rot || 0) * Math.PI) / 180;
  const c = Math.cos(th); const s = Math.sin(th);
  const pr = makeProjector({ lat: g.lat, lng: g.lng });
  return g.strokes.map((st) => st.map(([x, y]) => {
    const X = (x - ax) * k; const Y = (y - ay) * k;
    return pr.toLatLng([c * X - s * Y, s * X + c * Y]);
  }));
}
